    function extractShortVectorSymbol(rawText, localizedText) {
      if (SHORT_VECTOR_SYMBOL_MAP[rawText]) return SHORT_VECTOR_SYMBOL_MAP[rawText];
      let s = String(localizedText || rawText || '').trim();
      // Прибираємо пояснення в дужках у кінці або всередині (наприклад, "F₁₂ (Ampere force)" -> "F₁₂")
      s = s.replace(/\s*\([^)]*\)/g, '').trim();
      // Якщо є формула через "=", залишаємо лівий символ (наприклад, "F_c = mω²R" -> "F_c")
      if (s.includes('=')) {
        s = s.split('=')[0].trim();
      }
      if (s.length > 12 && s.includes(' ')) {
        const tokens = s.split(/\s+/);
        s = tokens[0];
      }
      return s || 'F';
    }

    function drawPillRect(ctx, x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    function makeBookVectorSprite(text, borderColor = '#142e46') {
      const localized = (typeof uiState === 'undefined' || uiState.lang === 'en')
        ? (VECTOR_LABEL_EN[text] || text)
        : text;
      const symbolText = extractShortVectorSymbol(text, localized);

      const canvas = document.createElement('canvas');
      const ctx = canvas.getContext('2d');
      const fontStr = '700 22px "IBM Plex Mono", "Georgia", monospace';
      ctx.font = fontStr;

      const measuredW = Math.ceil(ctx.measureText(symbolText).width);
      const padOuter = 6;
      const pillH = 38;
      const pillW = Math.max(38, measuredW + 20);

      canvas.width = pillW + padOuter * 2;
      canvas.height = pillH + padOuter * 2;

      // Компактна креслярська виноска з чітким кантом кольору вектора
      ctx.save();
      ctx.shadowColor = 'rgba(24, 24, 27, 0.14)';
      ctx.shadowBlur = 3;
      ctx.shadowOffsetY = 1;
      drawPillRect(ctx, padOuter, padOuter, pillW, pillH, 3);
      ctx.fillStyle = 'rgba(250, 249, 245, 0.95)';
      ctx.fill();
      ctx.restore();

      drawPillRect(ctx, padOuter, padOuter, pillW, pillH, 3);
      ctx.strokeStyle = borderColor;
      ctx.lineWidth = 2.0;
      ctx.stroke();

      // Тонкий верхній кутовий штрих для технічного стилю
      ctx.fillStyle = borderColor;
      ctx.fillRect(padOuter, padOuter, 5, 5);

      ctx.font = fontStr;
      ctx.fillStyle = '#18181b';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(symbolText, padOuter + pillW / 2, padOuter + pillH / 2 + 1);

      const texture = new THREE.CanvasTexture(canvas);
      texture.colorSpace = THREE.SRGBColorSpace;
      texture.minFilter = THREE.LinearFilter;
      const spriteMat = new THREE.SpriteMaterial({
        map: texture,
        transparent: true,
        depthTest: false,
        toneMapped: false
      });
      const sprite = new THREE.Sprite(spriteMat);
      const spriteH = 0.23;
      const spriteW = spriteH * (canvas.width / canvas.height);
      sprite.scale.set(spriteW, spriteH, 1);
      sprite.renderOrder = 999;
      return sprite;
    }

    function disposeObject3D(obj) {
      if (!obj) return;
      if (obj.children && obj.children.length > 0) {
        for (let i = obj.children.length - 1; i >= 0; i--) {
          disposeObject3D(obj.children[i]);
        }
      }
      if (obj.geometry && (!obj.geometry.userData || !obj.geometry.userData.persistent)) {
        obj.geometry.dispose();
      }
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        for (const m of mats) {
          if (!m) continue;
          if (m.map && (!m.map.userData || !m.map.userData.persistent)) m.map.dispose();
          if (m.bumpMap && (!m.bumpMap.userData || !m.bumpMap.userData.persistent)) m.bumpMap.dispose();
          if (!m.userData || !m.userData.persistent) m.dispose();
        }
      }
      if (obj.parent) {
        obj.parent.remove(obj);
      }
    }

    function clearGroup3D(group) {
      if (!group) return;
      while (group.children.length > 0) {
        disposeObject3D(group.children[0]);
      }
    }

    class SmartVectorArrow {
      constructor(label, colorHex = 0x166534, labelStrColor = '#166534') {
        if (label && typeof label === 'object' && labelStrColor && typeof labelStrColor === 'object') {
          label = labelStrColor.labelUk || labelStrColor.labelEn || 'F';
          labelStrColor = '#' + new THREE.Color(colorHex).getHexString();
        }
        this.rawLabel = String(label || 'F');
        const resolvedCssColor = (typeof labelStrColor === 'string' && labelStrColor.startsWith('#'))
          ? labelStrColor
          : ('#' + new THREE.Color(colorHex).getHexString());
        this.labelStrColor = resolvedCssColor;
        this.group = new THREE.Group();
        this.idealLabelPos = new THREE.Vector3();

        // Тонкий креслярський стрижень + опорне кільце в точці прикладання + гостре вістря
        const collarGeo = new THREE.CylinderGeometry(0.038, 0.038, 0.025, 16);
        collarGeo.translate(0, 0.0125, 0);
        const shaftGeo = new THREE.CylinderGeometry(0.021, 0.021, 1, 16);
        shaftGeo.translate(0, 0.5, 0);
        const headGeo = new THREE.ConeGeometry(0.068, 0.24, 20);
        headGeo.translate(0, 0.12, 0);

        const mat = new THREE.MeshStandardMaterial({
          color: colorHex,
          roughness: 0.28,
          metalness: 0.22
        });

        this.collar = new THREE.Mesh(collarGeo, mat);
        this.shaft = new THREE.Mesh(shaftGeo, mat);
        this.head = new THREE.Mesh(headGeo, mat);

        const headEdges = new THREE.LineSegments(
          new THREE.EdgesGeometry(headGeo, 35),
          new THREE.LineBasicMaterial({ color: 0x18181b, transparent: true, opacity: 0.28 })
        );
        headEdges.raycast = () => {};
        this.head.add(headEdges);

        this.group.add(this.collar, this.shaft, this.head);

        this.labelSprite = makeBookVectorSprite(label, resolvedCssColor);
        scene.add(this.labelSprite);
        worldGroup.add(this.group);
        activeVectorArrows.add(this);
      }

      refreshLanguage() {
        const pos = this.labelSprite.position.clone();
        const vis = this.labelSprite.visible;
        disposeObject3D(this.labelSprite);
        this.labelSprite = makeBookVectorSprite(this.rawLabel, this.labelStrColor);
        this.labelSprite.position.copy(pos);
        this.labelSprite.visible = vis;
        scene.add(this.labelSprite);
      }

      update(origin, dirVector, length, showArrow = uiState.showVectors, showLabel = uiState.showLabels) {
        const effShowArrow = Boolean(showArrow);
        const effShowLabel = arguments.length >= 5 ? Boolean(showLabel) : (effShowArrow && Boolean(uiState.showLabels));
        if (!effShowArrow || length < 0.08 || !dirVector || dirVector.lengthSq() < 1e-9) {
          this.group.visible = false;
          this.labelSprite.visible = false;
          return;
        }
        this.group.visible = true;
        this.group.position.copy(origin);

        const normDir = dirVector.clone().normalize();
        const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), normDir);
        this.group.quaternion.copy(quat);

        const shaftLen = Math.max(0.04, length - 0.22);
        this.shaft.scale.set(1, shaftLen, 1);
        this.head.position.set(0, shaftLen, 0);

        this.labelSprite.visible = effShowLabel;
        if (effShowLabel) {
          const tipPos = origin.clone().addScaledVector(normDir, length + 0.22);
          this.idealLabelPos.copy(tipPos);
          this.labelSprite.position.copy(tipPos);
        }
      }

      dispose() {
        activeVectorArrows.delete(this);
        disposeObject3D(this.group);
        disposeObject3D(this.labelSprite);
      }
    }

    function deoverlapVectorLabels() {
      const visible = [];
      for (const arr of activeVectorArrows) {
        if (arr && arr.labelSprite && arr.labelSprite.visible && arr.idealLabelPos) {
          arr.labelSprite.position.copy(arr.idealLabelPos);
          visible.push(arr.labelSprite);
        }
      }
      if (visible.length === 0) return;

      // Push vector labels away from fixed 3D callout badges so they never collide
      if (typeof activeBioCalloutPins !== 'undefined' && activeBioCalloutPins.size > 0) {
        for (const vSprite of visible) {
          for (const pin of activeBioCalloutPins) {
            if (!pin || !pin.group || !pin.group.visible || !pin.sprite) continue;
            const pPos = pin.sprite.position;
            const dx = vSprite.position.x - pPos.x;
            const dy = vSprite.position.y - pPos.y;
            const dz = vSprite.position.z - pPos.z;
            const dist = Math.hypot(dx, dy, dz);
            const minPinDist = 0.78;
            if (dist < minPinDist) {
              const push = (minPinDist - dist) + 0.08;
              if (dist < 1e-4) {
                vSprite.position.y -= push;
              } else {
                vSprite.position.x += (dx / dist) * push * 0.65;
                vSprite.position.y += (dy / dist) * push * 0.95;
                vSprite.position.z += (dz / dist) * push * 0.35;
              }
            }
          }
        }
      }

      if (visible.length < 2) return;

      const minDist = 0.44;
      for (let pass = 0; pass < 3; pass++) {
        for (let i = 0; i < visible.length; i++) {
          for (let j = i + 1; j < visible.length; j++) {
            const a = visible[i].position;
            const b = visible[j].position;
            let dx = b.x - a.x;
            let dy = b.y - a.y;
            let dz = b.z - a.z;
            const dist = Math.hypot(dx, dy, dz);
            if (dist < minDist) {
              const push = (minDist - dist) * 0.52;
              if (dist < 1e-4) {
                a.y += push;
                b.y -= push;
              } else {
                const inv = 1 / dist;
                // Переважно розштовхуємо по вертикалі та горизонталі, щоб виноски читались каскадом
                const nx = dx * inv * 0.65;
                const ny = (Math.abs(dy) < 0.08 ? (i % 2 === 0 ? 1 : -1) * 0.85 : dy * inv * 1.15);
                const nz = dz * inv * 0.35;
                const nLen = Math.hypot(nx, ny, nz) || 1;
                a.x -= (nx / nLen) * push;
                a.y -= (ny / nLen) * push;
                a.z -= (nz / nLen) * push;
                b.x += (nx / nLen) * push;
                b.y += (ny / nLen) * push;
                b.z += (nz / nLen) * push;
              }
            }
          }
        }
      }
    }

    class VectorArrow3D extends SmartVectorArrow {
      constructor(colorHex = 0x166534, label = 'v') {
        const hexStr = '#' + colorHex.toString(16).padStart(6, '0');
        super(label, colorHex, hexStr);
      }

      update(origin, dirVector, length, showArrowOrLabel = true, showLabel = true) {
        const showVec = typeof showArrowOrLabel === 'boolean' ? showArrowOrLabel : uiState.showVectors;
        const showLbl = typeof showArrowOrLabel === 'boolean' ? showLabel : uiState.showLabels;
        super.update(origin, dirVector, length, showVec, showLbl);
      }
    }

    class EnergyParticleSystem {
      constructor(maxParticles = 120) {
        const safeMax = (typeof maxParticles === 'number' && maxParticles > 0 && maxParticles <= 300) ? Math.floor(maxParticles) : 100;
        this.max = safeMax;
        this.particles = [];
        this.sharedGeo = new THREE.SphereGeometry(0.055, 8, 8);
        for (let i = 0; i < safeMax; i++) {
          const mat = new THREE.MeshBasicMaterial({
            color: 0xb45309,
            transparent: true,
            opacity: 0
          });
          const mesh = new THREE.Mesh(this.sharedGeo, mat);
          mesh.visible = false;
          worldGroup.add(mesh);
          this.particles.push({ mesh, vel: new THREE.Vector3(), life: 0, maxLife: 1 });
        }
        this.cursor = 0;
      }

      emit(pos, velocitySpread = 2.0, count = 4, colorHex = 0xb45309) {
        if (!uiState.showParticles || !this.particles.length) return;
        if (velocitySpread && typeof velocitySpread === 'object') {
          if (typeof count === 'number' && count > 256) colorHex = count;
          count = 2;
          velocitySpread = 1.4;
        }
        const safeCount = Math.min(24, Math.max(1, Number(count) || 2));
        for (let i = 0; i < safeCount; i++) {
          const p = this.particles[this.cursor];
          this.cursor = (this.cursor + 1) % this.max;
          p.mesh.position.copy(pos);
          p.mesh.material.color.setHex(colorHex);
          p.mesh.material.opacity = 0.9;
          p.mesh.scale.setScalar(1);
          p.mesh.visible = true;
          p.vel.set(
            (Math.random() - 0.5) * velocitySpread,
            Math.random() * velocitySpread * 0.75 + 0.35,
            (Math.random() - 0.5) * velocitySpread
          );
          p.life = 0;
          p.maxLife = 0.4 + Math.random() * 0.4;
        }
      }

      update(dt) {
        for (const p of this.particles) {
          if (!p.mesh.visible) continue;
          p.life += dt;
          if (p.life >= p.maxLife) {
            p.mesh.visible = false;
            continue;
          }
          p.mesh.position.addScaledVector(p.vel, dt);
          const ratio = 1 - p.life / p.maxLife;
          p.mesh.material.opacity = ratio * 0.85;
          p.mesh.scale.setScalar(0.35 + ratio * 0.75);
        }
      }

      clear() {
        for (const p of this.particles) p.mesh.visible = false;
      }

      dispose() {
        for (const p of this.particles) {
          if (p.mesh.parent) p.mesh.parent.remove(p.mesh);
          if (p.mesh.material) p.mesh.material.dispose();
        }
        if (this.sharedGeo) this.sharedGeo.dispose();
        this.particles = [];
      }
    }

