          { key: 'kCat', label: 'Каталітичне число обертів ферменту k_cat (V_max)', min: 2.0, max: 14.0, step: 0.5, unit: 'с⁻¹' },
          { key: 'inhibitorI', label: 'Концентрація конкурентного інгібітора [I]', min: 0.0, max: 6.0, step: 0.5, unit: 'ммоль/л' }
