    const chartCanvas = document.getElementById('chart-canvas');
    const chartCtx = chartCanvas.getContext('2d');

    function formatMetricBarSlot(rawVal, rawLabel, sceneKey, isEn) {
      const lbl = String(rawLabel || '');
      let val = Number.isFinite(rawVal) ? rawVal : 0;

      // Unscale values where label indicates a visual multiplier like (×10), (×7), (×100)
      const multMatch = lbl.match(/\(×\s*(\d+(?:\.\d+)?)\s*([a-zA-Zа-яА-ЯіїєґІЇЄҐ%°]*)\)/);
      let explicitMultUnit = '';
      if (multMatch) {
        const factor = parseFloat(multMatch[1]);
        if (factor > 0) val = val / factor;
        explicitMultUnit = (multMatch[2] || '').trim();
      }

      if (sceneKey === 'bio_mendel' || sceneKey === 'bio_hemo') {
        return { text: `${val.toFixed(1)} %`, unit: '%', isEnergy: false };
      }
      if (sceneKey === 'bio_lotka') {
        if (/дисипац|dissip|10%/i.test(lbl)) {
          return { text: `${val.toFixed(1)} %`, unit: '%', isEnergy: false };
        }
        return { text: `${val.toFixed(0)} ${isEn ? 'ind.' : 'особ.'}`, unit: isEn ? 'ind.' : 'особ.', isEnergy: false };
      }
      if (sceneKey === 'bio_meiosis') {
        if (/пН|pN/i.test(lbl)) {
          const u = isEn ? 'pN' : 'пН';
          return { text: `${(val / 2).toFixed(1)} ${u}`, unit: u, isEnergy: false };
        }
        return { text: `${val.toFixed(1)} %`, unit: '%', isEnergy: false };
      }
      if (sceneKey === 'bio_eye') {
        if (/мм|mm|Δf/i.test(lbl)) {
          const u = isEn ? 'mm' : 'мм';
          return { text: `${(val / 20).toFixed(2)} ${u}`, unit: u, isEnergy: false };
        }
        const u = isEn ? 'dpt' : 'дптр';
        const dVal = /акомод|accom/i.test(lbl) ? (val / 3) : val;
        return { text: `${dVal.toFixed(1)} ${u}`, unit: u, isEnergy: false };
      }
      if (sceneKey === 'bio_synapse') {
        if (/везикул|vesicle|m\b/i.test(lbl)) {
          const u = isEn ? 'ves.' : 'вез.';
          return { text: `${(val / 2).toFixed(1)} ${u}`, unit: u, isEnergy: false };
        }
        if (/мВ|mV|ПСП|PSP/i.test(lbl)) {
          const u = isEn ? 'mV' : 'мВ';
          return { text: `${(val / 2).toFixed(1)} ${u}`, unit: u, isEnergy: false };
        }
        const u = isEn ? 'a.u.' : 'ум.од.';
        return { text: `${(val / 25).toFixed(2)} ${u}`, unit: u, isEnergy: false };
      }
      if (sceneKey === 'bio_pcr') {
        if (/°C/.test(lbl)) {
          return { text: `${val.toFixed(0)} °C`, unit: '°C', isEnergy: false };
        }
        if (/lg\s*N/i.test(lbl)) {
          return { text: `${(val / 6).toFixed(2)}`, unit: 'lg N', isEnergy: false };
        }
        return { text: `${val.toFixed(1)} %`, unit: '%', isEnergy: false };
      }
      if (sceneKey === 'bio_crispr') {
        const vPct = /стабільн|stabil/i.test(lbl) ? (val / 1.5) : val;
        return { text: `${vPct.toFixed(1)} %`, unit: '%', isEnergy: false };
      }
      if (sceneKey === 'bio_phage') {
        if (/атм|atm/i.test(lbl)) {
          const u = isEn ? 'atm' : 'атм';
          return { text: `${val.toFixed(1)} ${u}`, unit: u, isEnergy: false };
        }
        return { text: `${val.toFixed(0)} %`, unit: '%', isEnergy: false };
      }
      if (sceneKey === 'bio_hemodynamics') {
        if (/мл\/с|mL\/s/i.test(lbl)) {
          const u = isEn ? 'mL/s' : 'мл/с';
          return { text: `${(val * 5).toFixed(1)} ${u}`, unit: u, isEnergy: false };
        }
        if (/см\/с|cm\/s/i.test(lbl)) {
          const u = isEn ? 'cm/s' : 'см/с';
          return { text: `${val.toFixed(1)} ${u}`, unit: u, isEnergy: false };
        }
        const u = isEn ? 'a.u.' : 'ум.од.';
        return { text: `${(val / 5).toFixed(2)} ${u}`, unit: u, isEnergy: false };
      }
      if (sceneKey === 'bio_electrophoresis') {
        const u = isEn ? 'mm' : 'мм';
        return { text: `${val.toFixed(1)} ${u}`, unit: u, isEnergy: false };
      }
      if (sceneKey === 'photoelectric' || sceneKey === 'bohr' || sceneKey === 'compton' || sceneKey === 'chem_orbitals') {
        if (/Δλ|зсув|shift/i.test(lbl)) {
          return { text: `${val.toFixed(2)} ${isEn ? 'pm' : 'пм'}`, unit: isEn ? 'pm' : 'пм', isEnergy: false };
        }
        const uEv = isEn ? 'eV' : 'еВ';
        return { text: `${val.toFixed(2)} ${uEv}`, unit: uEv, isEnergy: true };
      }

      if (explicitMultUnit) {
        return { text: `${val.toFixed(2)} ${explicitMultUnit}`.trim(), unit: explicitMultUnit, isEnergy: false };
      }
      if (/\(%\)|%|частка.*%|вихід.*%|ступінь.*%|інверсії|коагуляції|заряду.*SoC|нативної спіралі|гетерозигот/i.test(lbl)) {
        return { text: `${val.toFixed(1)} %`, unit: '%', isEnergy: false };
      }
      if (/\(‰\)|‰/.test(lbl)) {
        return { text: `${val.toFixed(2)} ‰`, unit: '‰', isEnergy: false };
      }
      if (/\bpH\b/i.test(lbl)) {
        const phVal = (sceneKey === 'chem_titration' && val > 14.5) ? (val / 7) : ((val > 14.5) ? (val / 10) : val);
        return { text: `${phVal.toFixed(2)}`, unit: '', isEnergy: false };
      }
      if (/\bR_f\b|Індекс lg|Абсорбція A|Absorbance|Ступінь іонності|Хвильовий зсув|Фазовий зсув/i.test(lbl)) {
        return { text: `${val.toFixed(2)}`, unit: '', isEnergy: false };
      }
      if (/\(мВ\)|\(mV\)|ζ-потенціал|Zeta/i.test(lbl)) {
        const u = isEn ? 'mV' : 'мВ';
        return { text: `${val.toFixed(1)} ${u}`, unit: u, isEnergy: false };
      }
      if (/\(В\)|\(V\)|Напруга|ЕРС|Voltage|EMF/i.test(lbl)) {
        const u = isEn ? 'V' : 'В';
        const vScaled = val > 25 ? val / 10 : val;
        return { text: `${vScaled.toFixed(2)} ${u}`, unit: u, isEnergy: false };
      }
      if (/\(кПа\)|\(kPa\)|Тиск|Pressure|напір/i.test(lbl)) {
        const u = isEn ? 'kPa' : 'кПа';
        return { text: `${val.toFixed(1)} ${u}`, unit: u, isEnergy: false };
      }
      if (/\(°C\)|°C/i.test(lbl)) {
        return { text: `${val.toFixed(1)} °C`, unit: '°C', isEnergy: false };
      }
      if (/\(К\)|\(K\)|ΔT/i.test(lbl)) {
        const u = isEn ? 'K' : 'К';
        return { text: `${val.toFixed(2)} ${u}`, unit: u, isEnergy: false };
      }
      if (/Дебаях|Debye|Диполь μ|Dipole/i.test(lbl)) {
        return { text: `${val.toFixed(2)} D`, unit: 'D', isEnergy: false };
      }
      if (/кДж\/моль|kJ\/mol|Ентальпія|Enthalpy|ΔH|ΔG|Δ_o|ЕСКП|CFSE|Енергія стабілізації|Енергія розщеплення|Потенціальна енергія уздовж|Potential Barrier/i.test(lbl)) {
        const u = isEn ? 'kJ/mol' : 'кДж/моль';
        return { text: `${val.toFixed(1)} ${u}`, unit: u, isEnergy: true };
      }
      if (/концентрація|Concentration|\[A\]|\[P\]|\[NO₂\]|\[N₂O₄\]|Розчинність S/i.test(lbl)) {
        const u = isEn ? 'mol/L' : 'моль/л';
        const cScaled = val > 10 ? val / 10 : val;
        return { text: `${cScaled.toFixed(2)} ${u}`, unit: u, isEnergy: false };
      }
      if (/швидкість реакції|Rate v|v₀|V_max|v_синт|v_реакц/i.test(lbl)) {
        const u = isEn ? 'mol/(L·s)' : 'моль/(л·с)';
        const rScaled = val > 10 ? val / 10 : val;
        return { text: `${rScaled.toFixed(2)} ${u}`, unit: u, isEnergy: false };
      }
      if (/Частота|Frequency f/i.test(lbl)) {
        const u = isEn ? 'Hz' : 'Гц';
        return { text: `${val.toFixed(1)} ${u}`, unit: u, isEnergy: false };
      }
      if (/Інтенсив|Intensity|Тіндаля|Tyndall|потік T|потік R|Flux/i.test(lbl)) {
        const u = isEn ? 'rel.' : 'відн.';
        return { text: `${val.toFixed(1)} ${u}`, unit: u, isEnergy: false };
      }

      const uJ = tUI().jouleUnit;
      return { text: `${val.toFixed(1)} ${uJ}`, unit: uJ, isEnergy: true };
    }

    function updateEnergyUI(ek, ep, q, maxRefEnergy, telemetryItems, skipHistory = false) {
      lastEnergyUIArgs = [ek, ep, q, maxRefEnergy, telemetryItems];
      const t = tUI();
      const isEn = uiState.lang === 'en';
      const sceneKey = uiState.activeScene;
      const cfg = SCENE_CONFIGS[sceneKey] || {};

      const s0 = formatMetricBarSlot(ek, cfg.ekLabel, sceneKey, isEn);
      const s1 = formatMetricBarSlot(ep, cfg.epLabel, sceneKey, isEn);
      const s2 = formatMetricBarSlot(q, cfg.qLabel, sceneKey, isEn);

      document.getElementById('ek-val').textContent = s0.text;
      document.getElementById('ep-val').textContent = s1.text;
      document.getElementById('q-val').textContent = s2.text;

      const tot = ek + ep + q;
      const titleEl = document.getElementById('ui-energy-balance-title');
      const totEl = document.getElementById('etot-val');
      if (sceneKey === 'bio_mendel') {
        if (titleEl) titleEl.textContent = isEn ? 'Genotype ratio' : 'Співвідношення генотипів';
        if (totEl) totEl.textContent = 'p² + 2pq + q² = 100%';
      } else if (s0.isEnergy && s1.isEnergy && s2.isEnergy && s0.unit === s1.unit && s1.unit === s2.unit) {
        if (titleEl) titleEl.textContent = t.energyBalanceTitle;
        if (totEl) totEl.textContent = `E = ${tot.toFixed(1)} ${s0.unit}`;
      } else {
        if (titleEl) titleEl.textContent = isEn ? 'Key indicators' : 'Ключові показники';
        if (totEl) totEl.textContent = s0.text;
      }

      const denom = Math.max(maxRefEnergy, tot, 0.01);
      document.getElementById('ek-bar').style.width = `${Math.min(100, Math.max(0, (ek / denom) * 100))}%`;
      document.getElementById('ep-bar').style.width = `${Math.min(100, Math.max(0, (ep / denom) * 100))}%`;
      document.getElementById('q-bar').style.width = `${Math.min(100, Math.max(0, (q / denom) * 100))}%`;

      const grid = document.getElementById('telemetry-grid');
      grid.innerHTML = telemetryItems
        .map(item => {
          const lbl = translateTelemetryLabel(item.label);
          const val = translateTelemetryVal(item.val);
          return `
        <div class="meas-cell">
          <span class="meas-name">${lbl}</span>
          <span class="meas-num">${val}</span>
        </div>`;
        })
        .join('');

      if (uiState.running && !skipHistory) {
        chartHistory.ek.push(ek / denom);
        chartHistory.ep.push(ep / denom);
        chartHistory.q.push(q / denom);
        if (chartHistory.ek.length > chartHistory.maxPoints) {
          chartHistory.ek.shift();
          chartHistory.ep.shift();
          chartHistory.q.shift();
        }
      }
      drawEnergyChart();
    }

    let chartHoverRatio = null;
    if (chartCanvas) {
      chartCanvas.addEventListener('mousemove', e => {
        const rect = chartCanvas.getBoundingClientRect();
        if (!rect.width) return;
        chartHoverRatio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
        drawEnergyChart();
      });
      chartCanvas.addEventListener('mouseleave', () => {
        chartHoverRatio = null;
        drawEnergyChart();
      });
      chartCanvas.addEventListener('dblclick', () => {
        resetChartHistory();
        drawEnergyChart();
      });
    }

    function drawEnergyChart() {
      const w = chartCanvas.width;
      const h = chartCanvas.height;
      chartCtx.clearRect(0, 0, w, h);

      chartCtx.strokeStyle = 'rgba(15, 23, 42, 0.07)';
      chartCtx.lineWidth = 1;
      for (let y = 18; y < h; y += 22) {
        chartCtx.beginPath();
        chartCtx.moveTo(0, y);
        chartCtx.lineTo(w, y);
        chartCtx.stroke();
      }

      const drawSeries = (arr, color, isDashed = false) => {
        if (!arr || arr.length < 2) return;
        chartCtx.save();
        chartCtx.strokeStyle = color;
        chartCtx.lineWidth = isDashed ? 1.4 : 1.8;
        if (isDashed) {
          chartCtx.setLineDash([4, 3]);
          chartCtx.globalAlpha = 0.55;
        }
        chartCtx.beginPath();
        for (let i = 0; i < arr.length; i++) {
          const x = (i / (chartHistory.maxPoints - 1)) * w;
          const y = h - 8 - Math.min(1, Math.max(0, arr[i])) * (h - 16);
          if (i === 0) chartCtx.moveTo(x, y);
          else chartCtx.lineTo(x, y);
        }
        chartCtx.stroke();
        chartCtx.restore();
      };

      if (pinnedChartHistory.active && pinnedChartHistory.scene === uiState.activeScene) {
        drawSeries(pinnedChartHistory.ek, '#16a34a', true);
        drawSeries(pinnedChartHistory.ep, '#2563eb', true);
        drawSeries(pinnedChartHistory.q, '#d97706', true);
      }

      drawSeries(chartHistory.ek, '#16a34a', false);
      drawSeries(chartHistory.ep, '#2563eb', false);
      drawSeries(chartHistory.q, '#d97706', false);

      if (chartHoverRatio !== null && chartHistory.ek.length >= 2) {
        const maxIdx = chartHistory.ek.length - 1;
        const idx = Math.max(0, Math.min(maxIdx, Math.round(chartHoverRatio * (chartHistory.maxPoints - 1))));
        const x = (idx / (chartHistory.maxPoints - 1)) * w;
        const vEk = chartHistory.ek[idx] ?? 0;
        const vEp = chartHistory.ep[idx] ?? 0;
        const vQ = chartHistory.q[idx] ?? 0;
        const denom = lastEnergyUIArgs ? Math.max(lastEnergyUIArgs[3] || 1, (lastEnergyUIArgs[0] || 0) + (lastEnergyUIArgs[1] || 0) + (lastEnergyUIArgs[2] || 0), 0.01) : 1;

        chartCtx.save();
        chartCtx.strokeStyle = 'rgba(24, 24, 27, 0.42)';
        chartCtx.lineWidth = 1;
        chartCtx.setLineDash([2, 2]);
        chartCtx.beginPath();
        chartCtx.moveTo(x, 4);
        chartCtx.lineTo(x, h - 4);
        chartCtx.stroke();
        chartCtx.setLineDash([]);

        [
          [vEk, '#16a34a'],
          [vEp, '#2563eb'],
          [vQ, '#d97706']
        ].forEach(([val, col]) => {
          const y = h - 8 - Math.min(1, Math.max(0, val)) * (h - 16);
          chartCtx.fillStyle = '#ffffff';
          chartCtx.strokeStyle = col;
          chartCtx.lineWidth = 1.8;
          chartCtx.beginPath();
          chartCtx.arc(x, y, 3.2, 0, Math.PI * 2);
          chartCtx.fill();
          chartCtx.stroke();
        });

        const fmtN = v => {
          const realV = v * denom;
          return realV >= 100 ? realV.toFixed(0) : (realV >= 10 ? realV.toFixed(1) : realV.toFixed(2));
        };
        const labelTxt = `${fmtN(vEk)} · ${fmtN(vEp)} · ${fmtN(vQ)}`;
        chartCtx.font = '600 10px "IBM Plex Mono", monospace';
        const tw = chartCtx.measureText(labelTxt).width + 10;
        const bx = Math.max(4, Math.min(w - tw - 4, x - tw / 2));
        chartCtx.fillStyle = 'rgba(255, 255, 255, 0.92)';
        chartCtx.strokeStyle = 'rgba(24, 24, 27, 0.18)';
        chartCtx.lineWidth = 1;
        chartCtx.fillRect(bx, 4, tw, 15);
        chartCtx.strokeRect(bx, 4, tw, 15);
        chartCtx.fillStyle = '#18181b';
        chartCtx.textBaseline = 'middle';
        chartCtx.fillText(labelTxt, bx + 5, 11.5);
        chartCtx.restore();
      }
    }

    function updateLiveFormulaSubstitution() {
      const key = uiState.activeScene;
      const cfg = SCENE_CONFIGS[key];
      const p = sceneParams[key];

      document.getElementById('reference-formula-box').innerHTML = renderStackedMath(cfg.referenceLatex);
      document.getElementById('explain-formula-katex').innerHTML = renderStackedMath(cfg.formulaLatex);
      if (cfg.liveLatexFn) {
        document.getElementById('explain-live-katex').innerHTML = renderLiveMathChips(cfg.liveLatexFn(p));
      }
      requestAnimationFrame(fitMathContainers);
    }

    function transitionToPhase(newPhase) {
      uiState.phase = newPhase;
      const t = tUI();

      const cPredict = document.getElementById('crumb-predict');
      const cTest = document.getElementById('crumb-test');
      const cExplain = document.getElementById('crumb-explain');

      const predictSection = document.getElementById('predict-section');
      const collapsedPrediction = document.getElementById('collapsed-prediction');
      const obsBanner = document.getElementById('observe-stage-banner');
      const actionStage = document.getElementById('action-stage');
      const explainStage = document.getElementById('explain-stage');

      cPredict.className = 'phase-crumb';
      cTest.className = 'phase-crumb';
      cExplain.className = 'phase-crumb';
      actionStage.classList.add('visible');

      if (newPhase === 'predict') {
        cPredict.classList.add('current');
        predictSection.style.display = 'flex';
        collapsedPrediction.classList.remove('visible');
        if (obsBanner) obsBanner.classList.remove('visible');
        explainStage.classList.remove('visible');
        syncActionButtons();
      } else if (newPhase === 'test') {
        cPredict.classList.add('done');
        cTest.classList.add('current');
        predictSection.style.display = uiState.selectedOption !== null ? 'none' : 'flex';
        if (uiState.selectedOption !== null) {
          collapsedPrediction.classList.add('visible');
          if (obsBanner) obsBanner.classList.add('visible');
        } else {
          collapsedPrediction.classList.remove('visible');
          if (obsBanner) obsBanner.classList.remove('visible');
        }
        explainStage.classList.remove('visible');
        syncActionButtons();
      } else if (newPhase === 'explain') {
        cPredict.classList.add('done');
        cTest.classList.add('done');
        cExplain.classList.add('current');
        if (obsBanner) obsBanner.classList.remove('visible');

        if (uiState.selectedOption !== null) {
          predictSection.style.display = 'none';
          collapsedPrediction.classList.add('visible');
        } else {
          predictSection.style.display = 'flex';
          collapsedPrediction.classList.remove('visible');
        }
        explainStage.classList.add('visible');

        const cfg = SCENE_CONFIGS[uiState.activeScene];
        const verdictBanner = document.getElementById('verdict-banner');
        if (uiState.selectedOption !== null) {
          const isCorrect = uiState.selectedOption === cfg.correctIndex;
          verdictBanner.style.display = 'block';
          verdictBanner.className = `proof-verdict ${isCorrect ? 'correct' : 'incorrect'}`;
          verdictBanner.textContent = isCorrect ? t.verdictCorrect : t.verdictIncorrect;
          if (isCorrect) {
            markExperimentMastered(uiState.activeScene);
          }
        } else {
          const correctLetter = t.letters[cfg.correctIndex] || 'B';
          verdictBanner.style.display = 'block';
          verdictBanner.className = 'proof-verdict correct';
          verdictBanner.textContent = `${t.verdictCorrect} (${t.optionPrefix} ${correctLetter})`;
        }

        const nextCta = document.getElementById('btn-next-lesson-cta');
        if (nextCta) {
          const keys = getDisciplineSceneKeys(uiState.discipline);
          const nextKey = keys[(keys.indexOf(uiState.activeScene) + 1) % keys.length];
          const nextCfg = SCENE_CONFIGS[nextKey];
          nextCta.textContent = `${t.nextLessonPrefix} · ${nextCfg.secSym} ${nextCfg.shortTitle} →`;
        }

        document.getElementById('explain-text').innerHTML = formatStructuredProse(cfg.explanation);
        updateLiveFormulaSubstitution();
        syncActionButtons();
      }
    }

    function syncActionButtons() {
      const primaryCta = document.getElementById('btn-primary-cta');
      const pauseToggle = document.getElementById('btn-pause-toggle');
      const t = tUI();

      if (uiState.running) {
        primaryCta.style.display = 'none';
        pauseToggle.style.display = 'inline-flex';
        pauseToggle.textContent = t.pauseBtn;
      } else if (uiState.simTime === 0) {
        primaryCta.style.display = 'inline-flex';
        primaryCta.textContent = t.runExp;
        pauseToggle.style.display = 'none';
      } else {
        primaryCta.style.display = 'inline-flex';
        primaryCta.textContent = uiState.phase === 'explain' ? t.repeatExp : t.continueExp;
        pauseToggle.style.display = 'none';
      }
    }

    function updateSliderFill(inputEl) {
      const min = parseFloat(inputEl.min);
      const max = parseFloat(inputEl.max);
      const val = parseFloat(inputEl.value);
      const pct = ((val - min) / (max - min)) * 100;
      inputEl.style.setProperty('--progress', `${pct}%`);
    }

    function renderQuestionAndSliders() {
      const key = uiState.activeScene;
      const cfg = SCENE_CONFIGS[key];
      const t = tUI();

      document.getElementById('chapter-section-tag').textContent = cfg.secTag ? cfg.secTag.split('·').slice(0, 2).map(s => s.trim()).join(' · ') : cfg.secSym;
      document.getElementById('scene-title').textContent = cfg.title;
      document.getElementById('scene-epigraph').innerHTML = cfg.epigraph ? formatTextbookProse(cfg.epigraph.replace(/\s+—\s+/g, ', ')) : '';
      document.getElementById('figure-caption-text').innerHTML = cfg.figCaption ? formatTextbookProse(cfg.figCaption.replace(/\s+—\s+/g, ', ')) : '';

      const cleanMetricLabel = str => String(str || '').replace(/\s*\(×\s*\d+(?:\.\d+)?\s*([a-zA-Zа-яА-ЯіїєґІЇЄҐ%°]*)\)/g, (_, u) => u ? ` (${u})` : '');
      document.getElementById('ek-label').textContent = cleanMetricLabel(cfg.ekLabel);
      document.getElementById('ep-label').textContent = cleanMetricLabel(cfg.epLabel);
      document.getElementById('q-label').textContent = cleanMetricLabel(cfg.qLabel);

      document.getElementById('question-text').innerHTML = formatTextbookProse(cfg.question);

      const letters = t.letters;
      const optionsContainer = document.getElementById('options-container');
      optionsContainer.innerHTML = '';

      cfg.options.forEach((optText, idx) => {
        const btn = document.createElement('button');
        btn.className = `book-option-btn${uiState.selectedOption === idx ? ' selected' : ''}`;
        btn.innerHTML = `<span class="option-letter">${letters[idx]}</span><span style="min-width:0;overflow-wrap:break-word;">${formatTextbookProse(optText)}</span>`;
        btn.addEventListener('click', () => {
          uiState.selectedOption = idx;
          document.getElementById('chosen-option-summary').textContent = `${t.optionPrefix} ${letters[idx]}`;
          if (uiState.simTime < 1.2) {
            uiState.running = true;
            transitionToPhase('test');
          } else {
            transitionToPhase('explain');
          }
        });
        optionsContainer.appendChild(btn);
      });

      const slidersContainer = document.getElementById('sliders-container');
      slidersContainer.innerHTML = '';

      cfg.sliders.forEach(s => {
        const currentVal = sceneParams[key][s.key];
        const defVal = (cfg.defaults && cfg.defaults[s.key] !== undefined) ? cfg.defaults[s.key] : currentVal;
        let effStep = s.step;
        const isAligned = v => {
          const k = (v - s.min) / effStep;
          return Math.abs(k - Math.round(k)) < 1e-5;
        };
        if (!isAligned(currentVal) || !isAligned(defVal)) {
          const decOf = n => (String(n).split('.')[1] || '').length;
          const maxDec = Math.max(decOf(s.step), decOf(s.min), decOf(defVal), decOf(currentVal));
          effStep = maxDec > 0 ? Math.pow(10, -maxDec) : 1;
        }
        const effMin = Math.min(s.min, currentVal, defVal);
        const effMax = Math.max(s.max, currentVal, defVal);
        const item = document.createElement('div');
        item.className = 'param-control';
        item.innerHTML = `
          <div class="param-header">
            <span class="param-title">${s.label}</span>
            <span class="param-readout" id="readout-${s.key}">${currentVal}${s.unit ? ' ' + s.unit : ''}</span>
          </div>
          <input type="range" class="book-slider" data-param-key="${s.key}" min="${effMin}" max="${effMax}" step="${effStep}" value="${currentVal}" />
        `;
        slidersContainer.appendChild(item);

        const input = item.querySelector('input');
        const readout = item.querySelector('.param-readout');
        updateSliderFill(input);

        const applySliderValue = rawVal => {
          const clamped = Math.max(effMin, Math.min(effMax, rawVal));
          const decOf = n => (String(n).split('.')[1] || '').length;
          const stepDec = Math.max(decOf(effStep), decOf(rawVal));
          const val = Number(clamped.toFixed(Math.min(4, stepDec)));
          input.value = val;
          sceneParams[key][s.key] = val;
          readout.textContent = `${val}${s.unit ? ' ' + s.unit : ''}`;
          updateSliderFill(input);
          updateLiveFormulaSubstitution();
          activePresetMode = 'custom';
          document.querySelectorAll('#lab-presets-bar .preset-chip-btn').forEach(b => b.classList.remove('active'));

          if (!uiState.running && activeSim) {
            uiState.simTime = 0;
            const t = tUI();
            document.getElementById('sim-time-readout').textContent = `t = 0.00 ${t.secUnit}`;
            resetChartHistory();
            activeSim.reset();
            syncActionButtons();
          } else if (activeSim) {
            if (key === 'projectile') activeSim.computeVacuumCurve();
            if (typeof activeSim.syncVisuals === 'function') {
              activeSim.syncVisuals();
            }
          }
        };

        input.addEventListener('input', e => {
          applySliderValue(parseFloat(e.target.value));
        });

        input.addEventListener('dblclick', () => {
          applySliderValue(defVal);
        });

        readout.title = uiState.lang === 'uk' ? 'Натисніть, щоб ввести точне число' : 'Click to type exact value';
        readout.addEventListener('click', () => {
          if (readout.querySelector('input')) return;
          const cur = sceneParams[key][s.key];
          const inlineInp = document.createElement('input');
          inlineInp.type = 'number';
          inlineInp.className = 'param-inline-input';
          inlineInp.min = String(effMin);
          inlineInp.max = String(effMax);
          inlineInp.step = String(effStep);
          inlineInp.value = String(cur);
          readout.textContent = '';
          readout.appendChild(inlineInp);
          inlineInp.focus();
          inlineInp.select();

          let committed = false;
          const commit = () => {
            if (committed) return;
            committed = true;
            const parsed = parseFloat(inlineInp.value);
            if (!Number.isNaN(parsed)) {
              applySliderValue(parsed);
            } else {
              readout.textContent = `${sceneParams[key][s.key]}${s.unit ? ' ' + s.unit : ''}`;
            }
          };
          inlineInp.addEventListener('keydown', ev => {
            ev.stopPropagation();
            if (ev.key === 'Enter') {
              ev.preventDefault();
              commit();
            } else if (ev.key === 'Escape') {
              ev.preventDefault();
              committed = true;
              readout.textContent = `${sceneParams[key][s.key]}${s.unit ? ' ' + s.unit : ''}`;
            }
          });
          inlineInp.addEventListener('blur', commit);
        });
      });

      updateLiveFormulaSubstitution();
      updateTheoryDrawerContent();
    }

