    // ============================================================================
    const cadSharedCache = {
      woodTex: null,
      breadboardTex: null,
      metalBumpTex: null,
      solidEdgeMat: null,
      glassEdgeMat: null,
      darkSteelMat: null,
      brassMat: null,
      rubberFootMat: null
    };

    function getCadSharedAssets() {
      if (!cadSharedCache.woodTex) {
        const cw = document.createElement('canvas');
        cw.width = 512;
        cw.height = 512;
        const ctx = cw.getContext('2d');
        ctx.fillStyle = '#d8d0c3';
        ctx.fillRect(0, 0, 512, 512);
        for (let y = 0; y < 512; y += 2) {
          const v = Math.sin(y * 0.08) * 4 + Math.cos(y * 0.31) * 2;
          ctx.fillStyle = v > 0 ? 'rgba(180, 166, 145, 0.16)' : 'rgba(120, 108, 92, 0.10)';
          ctx.fillRect(0, y, 512, 2);
        }
        ctx.strokeStyle = 'rgba(110, 98, 82, 0.14)';
        ctx.lineWidth = 1;
        for (let i = 0; i < 48; i++) {
          const y0 = (i * 11) % 512;
          ctx.beginPath();
          ctx.moveTo(0, y0);
          ctx.bezierCurveTo(170, y0 + ((i % 3) - 1) * 6, 340, y0 - ((i % 3) - 1) * 6, 512, y0);
          ctx.stroke();
        }
        const tex = new THREE.CanvasTexture(cw);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(2, 1);
        tex.userData = { persistent: true };
        cadSharedCache.woodTex = tex;
      }

      if (!cadSharedCache.breadboardTex) {
        const cb = document.createElement('canvas');
        cb.width = 512;
        cb.height = 512;
        const ctx = cb.getContext('2d');
        ctx.fillStyle = '#222e3f';
        ctx.fillRect(0, 0, 512, 512);
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
        ctx.lineWidth = 1;
        for (let y = 0; y < 512; y += 3) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(512, y);
          ctx.stroke();
        }
        // Сітка різьбових отворів M6 оптичної плити
        for (let gx = 16; gx < 512; gx += 32) {
          for (let gy = 16; gy < 512; gy += 32) {
            ctx.fillStyle = 'rgba(10, 15, 26, 0.65)';
            ctx.beginPath();
            ctx.arc(gx, gy, 2.8, 0, Math.PI * 2);
            ctx.fill();
            ctx.strokeStyle = 'rgba(148, 163, 184, 0.22)';
            ctx.lineWidth = 0.8;
            ctx.stroke();
          }
        }
        const tex = new THREE.CanvasTexture(cb);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.repeat.set(2, 1);
        tex.userData = { persistent: true };
        cadSharedCache.breadboardTex = tex;
      }

      if (!cadSharedCache.metalBumpTex) {
        const cm = document.createElement('canvas');
        cm.width = 256;
        cm.height = 256;
        const ctx = cm.getContext('2d');
        ctx.fillStyle = '#808080';
        ctx.fillRect(0, 0, 256, 256);
        for (let y = 0; y < 256; y++) {
          const shade = 120 + ((y * 17) % 19);
          ctx.fillStyle = `rgb(${shade},${shade},${shade})`;
          ctx.fillRect(0, y, 256, 1);
        }
        const tex = new THREE.CanvasTexture(cm);
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        tex.userData = { persistent: true };
        cadSharedCache.metalBumpTex = tex;
      }

      if (!cadSharedCache.solidEdgeMat) {
        cadSharedCache.solidEdgeMat = new THREE.LineBasicMaterial({
          color: 0x1e293b,
          transparent: true,
          opacity: 0.23
        });
        cadSharedCache.solidEdgeMat.userData = { persistent: true };
      }

      if (!cadSharedCache.glassEdgeMat) {
        cadSharedCache.glassEdgeMat = new THREE.LineBasicMaterial({
          color: 0x475569,
          transparent: true,
          opacity: 0.34
        });
        cadSharedCache.glassEdgeMat.userData = { persistent: true };
      }

      if (!cadSharedCache.darkSteelMat) {
        cadSharedCache.darkSteelMat = new THREE.MeshStandardMaterial({
          color: 0x273244,
          metalness: 0.78,
          roughness: 0.28,
          bumpMap: cadSharedCache.metalBumpTex,
          bumpScale: 0.005
        });
        cadSharedCache.darkSteelMat.userData = { persistent: true };
      }

      if (!cadSharedCache.brassMat) {
        cadSharedCache.brassMat = new THREE.MeshStandardMaterial({
          color: 0xb45309,
          metalness: 0.85,
          roughness: 0.22
        });
        cadSharedCache.brassMat.userData = { persistent: true };
      }

      if (!cadSharedCache.rubberFootMat) {
        cadSharedCache.rubberFootMat = new THREE.MeshStandardMaterial({
          color: 0x18181b,
          metalness: 0.15,
          roughness: 0.82
        });
        cadSharedCache.rubberFootMat.userData = { persistent: true };
      }

      if (!cadSharedCache.enamelTickMat) {
        cadSharedCache.enamelTickMat = new THREE.MeshBasicMaterial({
          color: 0xe2e8f0,
          transparent: true,
          opacity: 0.72
        });
        cadSharedCache.enamelTickMat.userData = { persistent: true };
      }

      if (!cadSharedCache.screenGridTex) {
        const cs = document.createElement('canvas');
        cs.width = 512;
        cs.height = 512;
        const ctx = cs.getContext('2d');
        ctx.fillStyle = '#0f172a';
        ctx.fillRect(0, 0, 512, 512);
        ctx.strokeStyle = 'rgba(148, 163, 184, 0.14)';
        ctx.lineWidth = 1;
        for (let g = 0; g <= 512; g += 32) {
          ctx.beginPath();
          ctx.moveTo(g, 0);
          ctx.lineTo(g, 512);
          ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(0, g);
          ctx.lineTo(512, g);
          ctx.stroke();
        }
        ctx.strokeStyle = 'rgba(56, 189, 248, 0.26)';
        ctx.lineWidth = 1.5;
        for (let g = 0; g <= 512; g += 128) {
          ctx.beginPath();
          ctx.moveTo(g, 0);
          ctx.lineTo(g, 512);
          ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(0, g);
          ctx.lineTo(512, g);
          ctx.stroke();
        }
        const tex = new THREE.CanvasTexture(cs);
        tex.colorSpace = THREE.SRGBColorSpace;
        tex.userData = { persistent: true };
        cadSharedCache.screenGridTex = tex;
      }

      return cadSharedCache;
    }

    const LAB_PALETTE_REFINE = {
      0x38bdf8: 0x0369a1,
      0x7dd3fc: 0x0369a1,
      0x0ea5e9: 0x0369a1,
      0xfef08a: 0xd97706,
      0xfde047: 0xd97706,
      0xfacc15: 0xb45309,
      0xef4444: 0x991b1b,
      0xf87171: 0x991b1b,
      0xf43f5e: 0x991b1b,
      0x3b82f6: 0x1e40af,
      0x60a5fa: 0x1e40af,
      0x2563eb: 0x1e40af,
      0x22c55e: 0x166534,
      0x4ade80: 0x166534,
      0x10b981: 0x166534,
      0xf472b6: 0x991b1b,
      0xec4899: 0x991b1b,
      0xa855f7: 0x475569,
      0xc084fc: 0x475569,
      0x8b5cf6: 0x1e40af,
      0x7c3aed: 0x1e40af,
      0x6366f1: 0x1e40af,
      0xf97316: 0xb45309
    };

    function markNoRaycastRecursive(obj) {
      obj.raycast = () => {};
      obj.userData = Object.assign({}, obj.userData, { isCadHardware: true });
      if (obj.children) {
        for (const ch of obj.children) markNoRaycastRecursive(ch);
      }
    }

    function enhanceApparatusScene(rootGroup, sceneKey) {
      if (!rootGroup) return;
      const assets = getCadSharedAssets();
      const meshes = [];

      rootGroup.traverse(obj => {
        if (!obj || !obj.isMesh) return;
        if (obj.userData && (obj.userData.cadEnhanced || obj.userData.isCadHardware)) return;
        let cur = obj;
        while (cur) {
          for (const arr of activeVectorArrows) {
            if (cur === arr.group) return;
          }
          cur = cur.parent;
        }
        meshes.push(obj);
      });

      for (const mesh of meshes) {
        mesh.userData = Object.assign({}, mesh.userData, { cadEnhanced: true });
        const geo = mesh.geometry;
        if (!geo) continue;
        const gType = geo.type || '';
        const p = geo.parameters || {};

        // 1. Оновлюємо пласкі MeshBasicMaterial на об'ємних 3D-тілах до фізично освітлених MeshStandardMaterial
        if (mesh.material && !Array.isArray(mesh.material)) {
          const mat = mesh.material;
          const rawHex = (mat.color && typeof mat.color.getHex === 'function') ? mat.color.getHex() : null;
          const refinedHex = (rawHex !== null && LAB_PALETTE_REFINE[rawHex] !== undefined) ? LAB_PALETTE_REFINE[rawHex] : rawHex;

          if (mat.isMeshBasicMaterial && !mat.map && !mat.wireframe) {
            const isSolid3D = gType === 'SphereGeometry' || gType === 'CylinderGeometry' || gType === 'ConeGeometry' || gType === 'BoxGeometry' || gType === 'OctahedronGeometry' || gType === 'TorusGeometry';
            if (isSolid3D && (!mat.transparent || mat.opacity >= 0.35)) {
              const newMat = new THREE.MeshStandardMaterial({
                color: refinedHex !== null ? refinedHex : 0x0369a1,
                roughness: mat.transparent ? 0.34 : 0.30,
                metalness: mat.transparent ? 0.12 : 0.20,
                emissive: refinedHex !== null ? refinedHex : 0x0369a1,
                emissiveIntensity: mat.transparent ? 0.06 : 0.12,
                transparent: Boolean(mat.transparent),
                opacity: mat.opacity !== undefined ? mat.opacity : 1.0,
                depthWrite: mat.depthWrite !== undefined ? mat.depthWrite : true
              });
              mat.dispose();
              mesh.material = newMat;
            }
          } else if ((mat.isMeshStandardMaterial || mat.isMeshPhysicalMaterial) && !mesh.userData.periodicTile) {
            if (refinedHex !== null && refinedHex !== rawHex) {
              mat.color.setHex(refinedHex);
              if (mat.emissive && mat.emissiveIntensity > 0) {
                mat.emissive.setHex(refinedHex);
              }
            }
            if (mat.emissiveIntensity > 0.28 && (!mat.transparent || mat.opacity > 0.65)) {
              mat.emissiveIntensity = 0.18;
            }
            if (mat.metalness >= 0.45 && !mat.bumpMap && !mat.map && !mat.transparent) {
              mat.bumpMap = assets.metalBumpTex;
              mat.bumpScale = 0.005;
              mat.needsUpdate = true;
            }
            if (mat.transparent && mat.opacity >= 0.10 && mat.opacity <= 0.58) {
              mat.roughness = Math.min(mat.roughness, 0.12);
              mat.envMapIntensity = 1.65;
            }
          }
        }

        const mat = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material;
        const isTransparent = Boolean(mat && mat.transparent && mat.opacity < 0.62);
        const isVeryFaint = Boolean(mat && mat.transparent && mat.opacity < 0.18);
        const isPeriodicTile = Boolean(mesh.userData && mesh.userData.periodicTile);
        const isBioScene = Boolean(sceneKey && sceneKey.startsWith('bio_'));
        const isMolecularChem = Boolean(sceneKey && /^(chem_orbitals|chem_vsepr|chem_lattice|chem_organic|chem_periodic|chem_hbond|chem_isomerism|chem_polymer|chem_mo|chem_allotropes|chem_complex|chem_bornhaber|chem_dipole|chem_enzyme|chem_sn2|chem_biopol)$/.test(sceneKey));
        const isBioOrMolecular = isBioScene || isMolecularChem;

        // 2. Текстурування та кріплення основних лабораторних плит/стендів (BoxGeometry)
        if (gType === 'BoxGeometry' && !isPeriodicTile) {
          const w = p.width !== undefined ? p.width : 1;
          const h = p.height !== undefined ? p.height : 1;
          const d = p.depth !== undefined ? p.depth : 1;

          const worldPos = new THREE.Vector3();
          mesh.getWorldPosition(worldPos);
          const isUpright = Math.abs(mesh.rotation.x) < 0.05 && Math.abs(mesh.rotation.z) < 0.05;

          // Широка опорна плита лабораторного столу
          if (w >= 4.2 && h >= 0.14 && h <= 0.48 && d >= 1.5 && worldPos.y <= 0.68 && isUpright && !isTransparent) {
            if (isBioOrMolecular) {
              if (mat && mat.color) {
                mat.color.setHex(0xe5e0d5);
                mat.roughness = 0.78;
                mat.metalness = 0.04;
                mat.needsUpdate = true;
              }
            } else {
              const hex = (mat && mat.color) ? mat.color.getHex() : 0xd6cfc2;
              if (hex === 0xd6cfc2 || hex === 0xc2b69f || hex === 0xe2d9c8 || hex === 0xd6d3d1) {
                mat.map = assets.woodTex;
                mat.roughness = 0.58;
                mat.metalness = 0.06;
                mat.needsUpdate = true;
              } else if (hex === 0x1e293b || hex === 0x334155 || hex === 0x0f172a) {
                mat.map = assets.breadboardTex;
                mat.roughness = 0.42;
                mat.metalness = 0.52;
                mat.needsUpdate = true;
              }

              // 4 кутові шестигранні болти та 4 регульовані віброопори
              const hw = Math.max(0.4, w * 0.5 - 0.32);
              const hd = Math.max(0.3, d * 0.5 - 0.32);
              const corners = [[-hw, hd], [hw, hd], [-hw, -hd], [hw, -hd]];
              const hardwareGrp = new THREE.Group();
              for (const [cx, cz] of corners) {
                const boltHead = new THREE.Mesh(
                  new THREE.CylinderGeometry(0.065, 0.065, 0.024, 6),
                  assets.darkSteelMat
                );
                boltHead.position.set(cx, h * 0.5 + 0.012, cz);
                const washer = new THREE.Mesh(
                  new THREE.CylinderGeometry(0.095, 0.095, 0.010, 16),
                  assets.brassMat
                );
                washer.position.set(cx, h * 0.5 + 0.005, cz);
                hardwareGrp.add(boltHead, washer);

                if (worldPos.y - h * 0.5 >= -0.02) {
                  const foot = new THREE.Mesh(
                    new THREE.CylinderGeometry(0.14, 0.18, 0.06, 16),
                    assets.rubberFootMat
                  );
                  foot.position.set(cx, -h * 0.5 - 0.02, cz);
                  hardwareGrp.add(foot);
                }
              }

              // Фронтальний латунний шильдик приладу на передньому торці опорної плити
              const nameplate = new THREE.Mesh(
                new THREE.BoxGeometry(Math.min(1.15, w * 0.18), Math.min(0.11, h * 0.48), 0.022),
                assets.brassMat
              );
              nameplate.position.set(0, 0, d * 0.5 + 0.011);
              hardwareGrp.add(nameplate);

              markNoRaycastRecursive(hardwareGrp);
              mesh.add(hardwareGrp);
            }
          }

          // Вертикальні табло/екрани осцилографів та діаграм: сітка, металева рамка та опорні стійки до бази
          if (!isBioOrMolecular && w >= 1.8 && h >= 1.5 && d <= 0.30 && isUpright && !isTransparent && worldPos.y >= 1.0 && mesh.scale.x === 1 && mesh.scale.y === 1) {
            const hex = (mat && mat.color) ? mat.color.getHex() : 0;
            if ((hex === 0x0f172a || hex === 0x1e293b || hex === 0x111827) && !mat.map) {
              mat.map = assets.screenGridTex;
              mat.roughness = 0.32;
              mat.metalness = 0.25;
              mat.needsUpdate = true;
            }
            const boardGrp = new THREE.Group();
            const bz = 0.055;
            const topRim = new THREE.Mesh(new THREE.BoxGeometry(w + bz * 2, bz, d + 0.04), assets.darkSteelMat);
            topRim.position.y = h * 0.5 + bz * 0.5;
            const botRim = new THREE.Mesh(new THREE.BoxGeometry(w + bz * 2, bz, d + 0.04), assets.darkSteelMat);
            botRim.position.y = -h * 0.5 - bz * 0.5;
            const leftRim = new THREE.Mesh(new THREE.BoxGeometry(bz, h, d + 0.04), assets.darkSteelMat);
            leftRim.position.x = -w * 0.5 - bz * 0.5;
            const rightRim = new THREE.Mesh(new THREE.BoxGeometry(bz, h, d + 0.04), assets.darkSteelMat);
            rightRim.position.x = w * 0.5 + bz * 0.5;
            boardGrp.add(topRim, botRim, leftRim, rightRim);

            const botY = worldPos.y - h * 0.5;
            if (botY > 0.26 && botY < 1.8) {
              const legH = botY - 0.24;
              for (const sx of [-w * 0.35, w * 0.35]) {
                const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.065, legH, 14), assets.darkSteelMat);
                leg.position.set(sx, -h * 0.5 - legH * 0.5, 0);
                const footFlange = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.15, 0.04, 16), assets.brassMat);
                footFlange.position.set(sx, -h * 0.5 - legH + 0.02, 0);
                boardGrp.add(leg, footFlange);
              }
            }
            markNoRaycastRecursive(boardGrp);
            mesh.add(boardGrp);
          }

          // Вертикальні електродні/конденсаторні пластини: ізоляторна стійка до бази
          if (!isBioOrMolecular && w <= 0.32 && h >= 1.5 && d >= 1.5 && isUpright && !isTransparent && mesh.scale.y === 1) {
            const botY = worldPos.y - h * 0.5;
            if (botY > 0.26 && botY < 1.5) {
              const legH = botY - 0.24;
              const insGrp = new THREE.Group();
              const post = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.09, legH, 16), assets.darkSteelMat);
              post.position.y = -h * 0.5 - legH * 0.5;
              const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.13, 0.05, 16), assets.brassMat);
              collar.position.y = -h * 0.5 - 0.025;
              insGrp.add(post, collar);
              markNoRaycastRecursive(insGrp);
              mesh.add(insGrp);
            }
          }

          // Чіткі креслярські ребра (EdgesGeometry) для прямокутних деталей приладів
          const minDim = Math.min(w, h, d);
          const maxDim = Math.max(w, h, d);
          if (!isBioOrMolecular && maxDim >= 0.20 && minDim >= 0.035 && !isVeryFaint) {
            const edges = new THREE.LineSegments(
              new THREE.EdgesGeometry(geo, 28),
              isTransparent ? assets.glassEdgeMat : assets.solidEdgeMat
            );
            markNoRaycastRecursive(edges);
            mesh.add(edges);
          }
        }

        // 3. Деталізація вертикальних стійок, штативів, циліндрів та скляних колб (CylinderGeometry)
        if (gType === 'CylinderGeometry' && !isBioOrMolecular) {
          const rTop = p.radiusTop !== undefined ? p.radiusTop : 0.1;
          const rBot = p.radiusBottom !== undefined ? p.radiusBottom : 0.1;
          const h = p.height !== undefined ? p.height : 1;
          const rAvg = (rTop + rBot) * 0.5;
          const isUpright = Math.abs(mesh.rotation.x) < 0.05 && Math.abs(mesh.rotation.z) < 0.05;
          const worldPos = new THREE.Vector3();
          mesh.getWorldPosition(worldPos);

          // Вертикальні металеві опорні колони штативів: додаємо нижній фланець на болтах та верхню муфту з латунним гвинтом
          const isDynamicRod = (mesh.scale.y !== 1) || (sceneKey === 'ampere' && rAvg < 0.09);
          if (isUpright && !isTransparent && !isDynamicRod && rAvg >= 0.055 && rAvg <= 0.23 && h >= 1.45 && (worldPos.y - h * 0.5 <= 0.85)) {
            const postHardware = new THREE.Group();

            // Ступінчастий опорний фланець внизу стійки
            const flangeBase = new THREE.Mesh(
              new THREE.CylinderGeometry(rBot * 2.05, rBot * 2.25, 0.07, 20),
              assets.darkSteelMat
            );
            flangeBase.position.y = -h * 0.5 + 0.035;
            const flangeNeck = new THREE.Mesh(
              new THREE.CylinderGeometry(rBot * 1.45, rBot * 1.65, 0.09, 18),
              assets.darkSteelMat
            );
            flangeNeck.position.y = -h * 0.5 + 0.10;
            const brassRing = new THREE.Mesh(
              new THREE.CylinderGeometry(rBot * 1.52, rBot * 1.52, 0.025, 18),
              assets.brassMat
            );
            brassRing.position.y = -h * 0.5 + 0.15;
            postHardware.add(flangeBase, flangeNeck, brassRing);

            // 4 кріпильні болти на фланці
            for (let b = 0; b < 4; b++) {
              const ang = (b * Math.PI) * 0.5 + Math.PI * 0.25;
              const br = rBot * 1.78;
              const fBolt = new THREE.Mesh(
                new THREE.CylinderGeometry(0.025, 0.025, 0.03, 6),
                assets.brassMat
              );
              fBolt.position.set(Math.cos(ang) * br, -h * 0.5 + 0.075, Math.sin(ang) * br);
              postHardware.add(fBolt);
            }

            // Верхня затискна муфта (bosshead) з накатаним латунним баранчиком
            const topCollar = new THREE.Mesh(
              new THREE.CylinderGeometry(rTop * 1.55, rTop * 1.55, 0.18, 18),
              assets.darkSteelMat
            );
            topCollar.position.y = h * 0.5 - 0.12;
            const thumbStem = new THREE.Mesh(
              new THREE.CylinderGeometry(0.028, 0.028, rTop * 2.2, 12),
              assets.brassMat
            );
            thumbStem.rotation.x = Math.PI / 2;
            thumbStem.position.set(0, h * 0.5 - 0.12, rTop * 1.6);
            const thumbKnob = new THREE.Mesh(
              new THREE.CylinderGeometry(0.068, 0.068, 0.045, 14),
              assets.brassMat
            );
            thumbKnob.rotation.x = Math.PI / 2;
            thumbKnob.position.set(0, h * 0.5 - 0.12, rTop * 2.55);
            postHardware.add(topCollar, thumbStem, thumbKnob);

            markNoRaycastRecursive(postHardware);
            mesh.add(postHardware);
          }

          // Відбортований скляний вінчик, скляне дно, мірна шкала та опорний триножник на прозорих лабораторних склянках і реакторах
          if (isUpright && isTransparent && !isVeryFaint && !isDynamicRod && rTop >= 0.36 && rTop <= 2.4 && h >= 0.85 && Math.abs(rTop - rBot) < 0.15) {
            const glassVesselGrp = new THREE.Group();
            const lipMat = new THREE.MeshPhysicalMaterial({
              color: 0xe2e8f0,
              transparent: true,
              opacity: Math.min(0.65, (mat.opacity || 0.25) + 0.22),
              roughness: 0.08,
              metalness: 0.05
            });
            const glassLip = new THREE.Mesh(new THREE.TorusGeometry(rTop, 0.022, 12, 36), lipMat);
            glassLip.rotation.x = Math.PI / 2;
            glassLip.position.y = h * 0.5;
            glassVesselGrp.add(glassLip);

            if (p.openEnded) {
              const botDisk = new THREE.Mesh(new THREE.CylinderGeometry(rBot, rBot, 0.035, 32), lipMat);
              botDisk.position.y = -h * 0.5 + 0.018;
              const botCollar = new THREE.Mesh(new THREE.TorusGeometry(rBot * 1.01, 0.026, 12, 36), assets.darkSteelMat);
              botCollar.rotation.x = Math.PI / 2;
              botCollar.position.y = -h * 0.5 + 0.02;
              glassVesselGrp.add(botDisk, botCollar);
            }

            // Градуйована емалева шкала об'єму на передній твірній циліндра
            const tickCount = 7;
            for (let t = 0; t <= tickCount; t++) {
              const ty = -h * 0.36 + (t / tickCount) * (h * 0.72);
              const isMaj = (t % 2 === 0);
              const tw = isMaj ? Math.min(0.22, rTop * 0.24) : Math.min(0.12, rTop * 0.14);
              const tick = new THREE.Mesh(new THREE.BoxGeometry(tw, 0.014, 0.012), assets.enamelTickMat);
              tick.position.set(rTop * 0.18, ty, rTop + 0.006);
              glassVesselGrp.add(tick);
            }

            // Якщо скляна колба/колона висить над базовою плитою, додаємо лабораторне опорне кільце зі стійками
            const botWorldY = worldPos.y - h * 0.5;
            if (botWorldY > 0.27 && botWorldY < 1.85) {
              const standH = botWorldY - 0.24;
              const ringSupport = new THREE.Mesh(new THREE.TorusGeometry(rBot * 0.96, 0.032, 12, 32), assets.darkSteelMat);
              ringSupport.rotation.x = Math.PI / 2;
              ringSupport.position.y = -h * 0.5 - 0.015;
              glassVesselGrp.add(ringSupport);

              for (let k = 0; k < 3; k++) {
                const ang = (k * Math.PI * 2) / 3 + Math.PI / 6;
                const lx = Math.cos(ang) * (rBot * 0.92);
                const lz = Math.sin(ang) * (rBot * 0.92);
                const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.045, standH, 12), assets.darkSteelMat);
                leg.position.set(lx, -h * 0.5 - standH * 0.5, lz);
                const foot = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.085, 0.03, 12), assets.brassMat);
                foot.position.set(lx, -h * 0.5 - standH + 0.015, lz);
                glassVesselGrp.add(leg, foot);
              }
            }

            markNoRaycastRecursive(glassVesselGrp);
            mesh.add(glassVesselGrp);
          }

          // Горизонтальні циліндричні перекладини та шини: точені латунні торцеві муфти
          const isHorizX = Math.abs(Math.abs(mesh.rotation.z) - Math.PI / 2) < 0.08 && Math.abs(mesh.rotation.x) < 0.08;
          if (isHorizX && !isTransparent && !isDynamicRod && rAvg >= 0.035 && rAvg <= 0.16 && h >= 2.2) {
            const capGrp = new THREE.Group();
            for (const s of [-1, 1]) {
              const cap = new THREE.Mesh(new THREE.CylinderGeometry(rAvg * 1.35, rAvg * 1.35, 0.08, 16), assets.brassMat);
              cap.position.y = s * (h * 0.5 - 0.04);
              capGrp.add(cap);
            }
            markNoRaycastRecursive(capGrp);
            mesh.add(capGrp);
          }

          // Креслярський контур торців циліндра
          if (rAvg >= 0.065 && h >= 0.12 && !isVeryFaint && !isDynamicRod) {
            const cylEdges = new THREE.LineSegments(
              new THREE.EdgesGeometry(geo, 28),
              isTransparent ? assets.glassEdgeMat : assets.solidEdgeMat
            );
            markNoRaycastRecursive(cylEdges);
            mesh.add(cylEdges);
          }
        }
      }
    }

    function resetCurrentSimulation(keepPhaseTest = true) {
      uiState.running = false;
      uiState.simTime = 0;
      document.getElementById('sim-time-readout').textContent = `t = 0.00 ${tUI().secUnit}`;
      resetChartHistory();
      if (activeSim) activeSim.reset();
      deoverlapVectorLabels();
      if (keepPhaseTest && uiState.selectedOption !== null) {
        transitionToPhase(uiState.phase === 'explain' ? 'explain' : 'test');
      }
      syncActionButtons();
    }

    document.getElementById('btn-change-prediction').addEventListener('click', () => {
      transitionToPhase('predict');
    });

    document.getElementById('btn-primary-cta').addEventListener('click', () => {
      if (uiState.phase === 'explain' && uiState.simTime > 0 && !uiState.running) {
        resetCurrentSimulation(true);
        uiState.running = true;
        syncActionButtons();
        return;
      }
      uiState.running = true;
      if (uiState.phase === 'predict' && uiState.selectedOption === null) {
        transitionToPhase('test');
      } else {
        syncActionButtons();
      }
    });

    document.getElementById('btn-pause-toggle').addEventListener('click', () => {
      uiState.running = !uiState.running;
      syncActionButtons();
    });

    document.getElementById('btn-step').addEventListener('click', () => {
      uiState.running = false;
      if (activeSim) {
        uiState.simTime += 0.02;
        document.getElementById('sim-time-readout').textContent = `t = ${uiState.simTime.toFixed(2)} ${tUI().secUnit}`;
        activeSim.update(0.02);
      }
      syncActionButtons();
    });

    document.getElementById('btn-reset').addEventListener('click', () => {
      resetCurrentSimulation(true);
    });

